// <auto-imports> — generated by wire.mjs, do not edit by hand
import { tokenDocumentsForActorOnScene } from "./actors.js";
import { sceneInvalidatePending } from "./chat.js";
import { MODULE_ID, SOCKET_NAME } from "./constants.js";
import { bridgeTrace } from "./log.js";
import { computeSceneBackgroundVersion } from "./map.js";
import { isPrimaryActiveGm } from "./mobile-bridge.js";
import { hpMaxOverrideOf, routeAssetPath } from "./sheet.js";
// </auto-imports>
import { bridgeFlag } from "./flags.js";
// Scene/actor/condition push emission + hook registration — extracted from mobile-bridge.js.

export function emitSceneInvalidate(scene, kind) {
  if (!game.socket || !scene?.id) return;
  if (!isPrimaryActiveGm()) return;
  const key = `${scene.id}:${kind}`;

  const pending = sceneInvalidatePending.get(key);
  if (pending) {
    pending.again = true;
    return;
  }

  const schedule = () => setTimeout(() => {
    const state = sceneInvalidatePending.get(key);
    sceneInvalidatePending.delete(key);
    const payload = {
      sceneId: scene.id,
      kind,
      bgVersion: computeSceneBackgroundVersion(scene)
    };
    for (const user of game.users) {
      // Everyone but the tab doing the emitting. Skipping GMs would have been
      // right if a GM were always a desktop client, but the phone can be signed
      // in as one, and then it never hears that the scene moved at all.
      if (user.id === game.user?.id) continue;
      game.socket.emit(SOCKET_NAME, {
        event: "scene.invalidate",
        payload,
        meta: { targetUserId: user.id }
      });
    }
    // Something moved while this window was open: run another one so the state
    // that arrived after the payload was built is announced too.
    if (state?.again) sceneInvalidatePending.set(key, { timer: schedule(), again: false });
  }, 80);

  sceneInvalidatePending.set(key, { timer: schedule(), again: false });
}

/**
 * Tell the phones the turn order moved.
 *
 * Deliberately not a scene invalidate. Advancing a turn changes six circles
 * over the map, and answering it with a scene refresh would re-fetch tokens,
 * vision, drawings and the reachability flood fill for a fact that fits in a
 * short list. The phone hears this and asks for the order alone.
 *
 * No throttle: a turn changes when somebody presses a button, and the round
 * button in the browser goes backwards as well as forwards. Every one of those
 * is a fact the queue has to show.
 */
export function emitCombatInvalidate(combat) {
  if (!game.socket) return;
  if (!isPrimaryActiveGm()) return;
  const payload = { combatId: combat?.id ?? null };
  for (const user of game.users) {
    if (user.id === game.user?.id) continue;
    game.socket.emit(SOCKET_NAME, {
      event: "combat.invalidate",
      payload,
      meta: { targetUserId: user.id }
    });
  }
}

/** Coalesces the several hook calls one targeting change produces. */
export const userTargetPushTimers = new Map();

/**
 * Tell a phone what its user is aiming at.
 *
 * The list travels whole rather than as an invalidation. It is a handful of
 * ids, and sending it outright is the difference between a reticle that keeps
 * up with the browser and one that arrives a map refresh later.
 *
 * Read from `user.targets` directly rather than through the cached helper: the
 * helper falls back to the last list the phone set when the live one is empty,
 * which is exactly wrong here — clearing every target is the one change that
 * would then report the targets that were just released. The hook fires on this
 * client because this client's set changed, so the live set is the answer.
 */
export function emitUserTargets(user) {
  if (!game.socket || !user?.id) return;
  if (!isPrimaryActiveGm()) return;
  if (user.id === game.user?.id) return;
  if (userTargetPushTimers.has(user.id)) return;
  // Targeting several tokens at once fires the hook once per token; wait for
  // the burst to finish and send the list it settles on.
  userTargetPushTimers.set(user.id, setTimeout(() => {
    userTargetPushTimers.delete(user.id);
    game.socket.emit(SOCKET_NAME, {
      event: "token.targets",
      payload: { tokenIds: [...(user.targets ?? [])].map((t) => t.id) },
      meta: { targetUserId: user.id }
    });
  }, 60));
}

export const BACKGROUND_SCENE_CHANGE_KEYS = ["background", "foreground", "width", "height", "padding", "grid"];
export const DYNAMIC_TOKEN_CHANGE_KEYS = ["x", "y", "hidden", "rotation", "elevation", "width", "height", "texture"];

/** Hooks that turn out-of-band scene mutations into client invalidation pushes. */
export function registerSceneInvalidateHooks() {
  Hooks.on("createToken", (doc) => emitSceneInvalidate(doc.parent, "dynamic"));
  Hooks.on("deleteToken", (doc) => emitSceneInvalidate(doc.parent, "dynamic"));
  Hooks.on("updateToken", (doc, changes, options) => {
    // `options.movement` catches a walk whose coordinates core folds into the
    // movement operation rather than into `changes`.
    if (options?.movement || DYNAMIC_TOKEN_CHANGE_KEYS.some((k) => k in changes)) {
      emitSceneInvalidate(doc.parent, "dynamic");
    }
  });
  for (const event of ["createWall", "updateWall", "deleteWall"]) {
    Hooks.on(event, (doc) => emitSceneInvalidate(doc.parent, "dynamic"));
  }
  for (const event of ["createAmbientLight", "updateAmbientLight", "deleteAmbientLight"]) {
    Hooks.on(event, (doc) => emitSceneInvalidate(doc.parent, "dynamic"));
  }
  for (const event of ["createMeasuredTemplate", "updateMeasuredTemplate", "deleteMeasuredTemplate"]) {
    Hooks.on(event, (doc) => emitSceneInvalidate(doc.parent, "dynamic"));
  }
  for (const event of ["createDrawing", "updateDrawing", "deleteDrawing"]) {
    Hooks.on(event, (doc) => emitSceneInvalidate(doc.parent, "dynamic"));
  }
  Hooks.on("updateScene", (doc, changes) => {
    const kind = BACKGROUND_SCENE_CHANGE_KEYS.some((k) => k in changes) ? "background" : "dynamic";
    emitSceneInvalidate(doc, kind);
  });
  // Status icons live on the actor, not the token, so an effect appearing or
  // going away changes what the map should show without touching any of the
  // documents above. Without this the badges only refresh on the next pan.
  // Marking a combatant defeated paints a skull on its token without touching
  // the token, the actor or any effect.
  for (const event of ["createCombatant", "updateCombatant", "deleteCombatant"]) {
    Hooks.on(event, (doc) => {
      if (canvas?.scene) emitSceneInvalidate(canvas.scene, "dynamic");
      emitCombatInvalidate(doc?.parent ?? null);
    });
  }
  // The turn itself lives on the Combat, not on any combatant: next, previous,
  // a new round and the end of the fight all arrive here and nowhere else.
  // Without this the queue only moved when something else happened to refresh
  // the map.
  Hooks.on("updateCombat", (doc) => emitCombatInvalidate(doc));
  // Pause is world-wide, not scene-scoped, but the only thing a phone polls
  // often enough to feel live is the scene snapshot it already has open —
  // reuse that push so the pause control (and the paused-gated door check)
  // catch up as soon as any GM flips it, not just at the next keep-alive.
  Hooks.on("pauseGame", () => {
    if (canvas?.scene) emitSceneInvalidate(canvas.scene, "dynamic");
  });
  // Fires for targeting done anywhere — the player's own browser, a macro, or
  // this bridge answering the phone — because it is the user's target set
  // itself that dispatches it.
  Hooks.on("targetToken", (user) => emitUserTargets(user));
  for (const event of ["createCombat", "deleteCombat"]) {
    Hooks.on(event, (doc) => emitCombatInvalidate(doc));
  }
  for (const event of ["createActiveEffect", "updateActiveEffect", "deleteActiveEffect"]) {
    Hooks.on(event, (effect) => {
      const actor = effect?.parent?.documentName === "Actor" ? effect.parent : null;
      if (!actor) return;
      const scene = canvas?.scene ?? null;
      if (!scene) return;
      if (tokenDocumentsForActorOnScene(actor, scene).length === 0) return;
      emitSceneInvalidate(scene, "dynamic");
    });
  }
}

/** Stash HP before apply so updateActor can emit old→new to mobile owners. */
export const pendingActorHpSnapshots = new Map();

/**
 * Push `actor.hp` when a PC's HP/temp changes (monster damage, healing, GM edit).
 * Emitted only from the updating client (has preUpdate snapshot) to avoid duplicates.
 */
export function registerActorHpPushHooks() {
  Hooks.on("preUpdateActor", (actor, changes) => {
    const hpChange = foundry.utils.getProperty(changes, "system.attributes.hp");
    if (!hpChange || typeof hpChange !== "object") return;
    if (!("value" in hpChange || "temp" in hpChange || "max" in hpChange)) return;
    const hp = actor.system?.attributes?.hp;
    if (!hp) return;
    pendingActorHpSnapshots.set(actor.id, {
      value: Number(hp.value) || 0,
      max: Number(hp.max) || 0,
      temp: Number(hp.temp) || 0
    });
  });
  Hooks.on("updateActor", (actor, changes) => {
    forwardActorHpToMobile(actor, changes);
  });
}

export function forwardActorHpToMobile(actor, changes) {
  if (!game.socket || !actor?.id) return;
  const hpChange = foundry.utils.getProperty(changes, "system.attributes.hp");
  if (!hpChange || typeof hpChange !== "object") return;
  if (!("value" in hpChange || "temp" in hpChange || "max" in hpChange)) return;

  const oldHp = pendingActorHpSnapshots.get(actor.id);
  pendingActorHpSnapshots.delete(actor.id);
  // Receiving clients only see updateActor — skip; the updater emits once.
  if (!oldHp) return;

  const hp = actor.system?.attributes?.hp;
  if (!hp) return;
  const newHp = Number(hp.value) || 0;
  const newMax = Number(hp.max) || 0;
  const newTemp = Number(hp.temp) || 0;
  // Max is compared too: editing only the max-HP override leaves value and temp
  // untouched, and without this the phone would keep showing the stale maximum.
  if (oldHp.value === newHp && oldHp.temp === newTemp && oldHp.max === newMax) return;

  const payload = {
    actorId: actor.id,
    actorName: actor.name ?? "",
    oldHp: oldHp.value,
    newHp,
    oldTemp: oldHp.temp,
    newTemp,
    oldHpMax: oldHp.max,
    hpMax: newMax,
    hpMaxOverride: hpMaxOverrideOf(actor),
    delta: newHp - oldHp.value,
    deltaTemp: newTemp - oldHp.temp
  };
  const users = game.users.filter((user) =>
    !user.isGM && actor.testUserPermission(user, "OWNER")
  );
  for (const user of users) {
    game.socket.emit(SOCKET_NAME, {
      event: "actor.hp",
      payload,
      meta: { targetUserId: user.id }
    });
  }
  if (users.length) {
    bridgeTrace("actor.hp", {
      actorId: payload.actorId,
      delta: payload.delta,
      oldHp: payload.oldHp,
      newHp: payload.newHp,
      recipients: users.map((u) => u.name)
    });
  }
}

/**
 * Push `actor.condition` when a temporary ActiveEffect is applied/removed on a PC
 * (status effects, spell buffs/debuffs). Primary GM only — create/delete hooks
 * fire on every client after replication.
 */
export function registerActorConditionPushHooks() {
  Hooks.on("createActiveEffect", (effect) => {
    forwardActorConditionToMobile(effect, "apply");
  });
  Hooks.on("deleteActiveEffect", (effect) => {
    forwardActorConditionToMobile(effect, "remove");
  });
}

export function summarizeConditionEffect(effect) {
  const rawImg = effect?.img ?? effect?.icon ?? null;
  const statuses = effect?.statuses instanceof Set
    ? [...effect.statuses]
    : Array.isArray(effect?.statuses) ? effect.statuses : [];
  return {
    id: effect?.id ?? (statuses[0] ?? effect?.name ?? ""),
    name: effect?.name ?? "",
    img: routeAssetPath(rawImg),
    statuses
  };
}

/** Same set of effects `buildBasicSheet` exposes as conditions. */
export function shouldForwardConditionEffect(effect) {
  if (!effect) return false;
  if (bridgeFlag(effect, "offlineOverride")) return false;
  if (effect.disabled) return false;
  if (typeof effect.isTemporary === "boolean") return effect.isTemporary;
  if (typeof effect.active === "boolean" && !effect.active) return false;
  const statuses = effect.statuses instanceof Set
    ? effect.statuses.size
    : (Array.isArray(effect.statuses) ? effect.statuses.length : 0);
  if (statuses > 0) return true;
  const dur = effect.duration ?? {};
  return !!(dur.seconds || dur.rounds || dur.turns || dur.startTime || dur.startRound || dur.startTurn);
}

export function forwardActorConditionToMobile(effect, action) {
  if (!game.socket || !isPrimaryActiveGm()) return;
  const actor = effect?.parent;
  if (!actor || actor.documentName !== "Actor") return;
  if (!shouldForwardConditionEffect(effect)) return;

  const summary = summarizeConditionEffect(effect);
  if (!summary.name && !summary.statuses.length) return;

  const payload = {
    actorId: actor.id,
    actorName: actor.name ?? "",
    action,
    ...summary
  };
  const users = game.users.filter((user) =>
    !user.isGM && actor.testUserPermission(user, "OWNER")
  );
  for (const user of users) {
    game.socket.emit(SOCKET_NAME, {
      event: "actor.condition",
      payload,
      meta: { targetUserId: user.id }
    });
  }
  if (users.length) {
    bridgeTrace("actor.condition", {
      actorId: payload.actorId,
      action,
      name: payload.name,
      statuses: payload.statuses,
      recipients: users.map((u) => u.name)
    });
  }
}

